func:
if (
    msg.payload === null ||
    msg.payload === undefined ||
    msg.payload === ""
) {
    node.warn("Please select Reject Date");
    return null;
}

var dt = new Date(msg.payload);

if (isNaN(dt.getTime())) {
    node.error("Invalid Reject Date: " + msg.payload);
    return null;
}

var rejectDate =
    dt.getFullYear() + "-" +
    String(dt.getMonth() + 1).padStart(2, "0") + "-" +
    String(dt.getDate()).padStart(2, "0");

global.set(
    "sendAllRejectDate",
    rejectDate
);

msg.payload = rejectDate;
msg.sendDate = rejectDate;

return msg;

if (!Array.isArray(msg.payload)) { node.error("ALL PIS_PRD_ORDER did not return an array"); return null; }
if (msg.payload.length === 0) { node.warn("No unsent lots found for " + (msg.productionDate || "")); return null; }
node.status({fill:"green",shape:"dot",text:msg.payload.length + " lot(s)"});
return msg;

var timeData = msg.payload;
var header = msg.header;

if (!header) {
    node.error("msg.header missing");
    return null;
}

function formatDate(d) {
    return d ? new Date(d).toISOString().split("T")[0] : "";
}

function formatDateTime(d) {
    return d ? new Date(d).toISOString().slice(0, 16) : "";
}

function trimVal(v) {
    if (typeof v === "string") return v.trim();
    if (typeof v === "number") return v.toString();
    return v || "";
}

function cleanRemark(r) {
    if (Array.isArray(r)) {
        return r
            .filter(x => x && String(x).trim() !== "")
            .join(" ")
            .trim();
    }
    return trimVal(r);
}


// =====================================================
// ITEM DETAILS + TASKS
// =====================================================

var itemDetailsList = [];

if (Array.isArray(timeData)) {

    timeData.forEach(function (row) {

        var tasksList = [];

        // มี PIS TaskCode -> สร้าง tasks[]
        if (trimVal(row.taskCode) !== "") {

            tasksList.push({
                taskCode: trimVal(row.taskCode),
                //duration: Number(row.duration || 0),
                duration: Math.max(1, Math.floor(Number(row.duration || 0))),
                serialNo: trimVal(row.serialNo),
                equipmentCode: trimVal(row.equipmentCode),
                failureCode: trimVal(row.failureCode),
                cause: trimVal(row.cause),
                solving: "",
                remark: cleanRemark(row.remark)
            });
        }

        itemDetailsList.push({
            downtimeCode: trimVal(row.downtimeCode),
            continue: false,
            startDateTime: formatDateTime(row.startDateTime),
            endDateTime: formatDateTime(row.endDateTime),
            repairNo: trimVal(row.repairNo) || "",
            remark: cleanRemark(row.remark),
            tasks: tasksList
        });
    });
}


// =====================================================
// PRODUCTION OUTPUT
// =====================================================

var outputCount = Number(header.gross0 || 0);
var cleanLot = trimVal(header.lotNo);
var cleanMat =
    trimVal(header.materialCode) ||
    "ZCB20NATA004000N35";


msg.payload = {

    productionDate:
        formatDate(header.productionDate),

    shiftCode:
        header.shiftCode || 2,

    plantCode:
        trimVal(header.plantCode || "3031"),

    machineCode:
        trimVal(header.Machine || "SB1-2"),

    operatorName:
        trimVal(header.operatorName),

    resources: [],

    lotNo:
        cleanLot,


    productionItem: {

        operationCode: "a",

        dateTimeStart:
            formatDateTime(header.dateTimeStart),

        dateTimeEnd:
            formatDateTime(header.dateTimeEnd),

        planWeek:
            trimVal(header.planWeek),

        planName:
            trimVal(header.planName),

        versionNo:
            trimVal(header.versionNo) || "01",

        followPlan:
            (
                header.followPlan === 1 ||
                header.followPlan === true
            ),

        remark:
            trimVal(header.remark_1),


        // =============================================
        // DOWNTIME + TASKS
        // =============================================

        itemDetails:
            itemDetailsList,


        // =============================================
        // OUTPUT
        // =============================================

        itemOutputs: [{
            materialCode:
                cleanMat,

            lotNo:
                cleanLot,

            gross0:
                outputCount,

            tool:
                "",

            remark:
                trimVal(header.remark_2),

            outputDetails: [{
                statusCode:
                    "Curing",

                lockProdOrderNo:
                    "",

                reasonCode:
                    trimVal(header.reasonCode),

                reasonCode2:
                    trimVal(header.reasonCode2),

                effectiveDate:
                    formatDate(header.productionDate),

                lockId:
                    "",

                count:
                    outputCount,

                remark:
                    ""
            }]
        }],


        itemInputs: [],


        itemProperties: [
            {
                propertyName: "น้ำหนักเฉลี่ย",
                propertyValue: 5.4
            },
            {
                propertyName: "ความชื้น",
                propertyValue: 9
            },
            {
                propertyName: "ความเร็วเครื่องจักร",
                propertyValue: 110
            },
            {
                propertyName: "Mould Oil",
                propertyValue: 5
            }
        ]
    }
};

return msg;

var rows = msg.payload;
if (!Array.isArray(rows) || rows.length === 0) { node.error("No built Lot items to group"); return null; }

var groups = {};
rows.forEach(function(row){
    var key = [row.productionDate,String(row.shiftCode),row.plantCode,row.machineCode].join("|");
    if (!groups[key]) {
        groups[key] = {
            productionDate: row.productionDate,
            shiftCode: row.shiftCode,
            plantCode: row.plantCode,
            machineCode: row.machineCode,
            operatorName: row.operatorName || "",
            resources: [],
            productionItems: [],
            lots: []
        };
    }
    groups[key].productionItems.push(row.productionItem);
    groups[key].lots.push(row.lotNo);
});

var outMsgs = [];
Object.keys(groups).sort().forEach(function(key){
    var g = groups[key];
    outMsgs.push({
        payload: {
            productionDate:g.productionDate,
            shiftCode:g.shiftCode,
            plantCode:g.plantCode,
            machineCode:g.machineCode,
            operatorName:g.operatorName,
            resources:g.resources,
            productionItems:g.productionItems
        },
        bulkLots:g.lots,
        bulkGroupKey:key,
        bulkGroupLotCount:g.lots.length
    });
});
node.status({fill:"green",shape:"dot",text:outMsgs.length+" group(s), "+rows.length+" lot(s)"});
return [outMsgs];

var lots = Array.isArray(msg.bulkLots) ? msg.bulkLots : [];
if (lots.length === 0) { node.error("bulkLots missing after PIS response"); return null; }

var data;
try { data = (typeof msg.payload === "string") ? JSON.parse(msg.payload) : msg.payload; }
catch(err) { data = {message:String(msg.payload || "")}; }

var isSuccess = String((data && data.message) || "").toLowerCase() === "success";
var retmsg = JSON.stringify(data).substring(0,100);

function sqlEscape(v){ return String(v == null ? "" : v).replace(/'/g,"''"); }
var values = lots.map(function(lotNo){
    return "('" + sqlEscape(String(lotNo).trim()) + "','" + sqlEscape(retmsg) + "',NULL," + (isSuccess ? 1 : 0) + ")";
}).join(",\n");

msg.topic = `
INSERT INTO PIS_API_RESULT
(lotNo, retmsg, OutputDetailId, IsSuccess)
VALUES
${values}`;

msg.bulkStatus = (isSuccess ? "SUCCESS" : "FAILED") + " | " + (msg.bulkGroupKey || "") + " | Lots: " + lots.join(", ") + " | " + retmsg;
msg.payload = msg.bulkStatus;
return msg;

var rows = msg.payload;

if (Array.isArray(rows) &&
    rows.length > 0 &&
    rows[0].DefaultProdDate) {

    var d = String(rows[0].DefaultProdDate).substring(0, 10);
    var count = Number(rows[0].PendingLotCount || 0);
    var source = String(rows[0].DateSource || "");

    // เก็บวันที่ YYYY-MM-DD สำหรับ SEND ALL PROD เหมือนเดิม
    global.set("sendAllRejectDate", d);

    // แปลงวันที่เป็น timestamp สำหรับ Bulk Production Date Picker
    // ใช้เวลา 12:00 เพื่อป้องกันปัญหาวันเลื่อนจาก timezone
    var p = d.split("-");
    var pickerDate = new Date(
        Number(p[0]),
        Number(p[1]) - 1,
        Number(p[2]),
        12, 0, 0
    );

    msg.payload = pickerDate.getTime();

    // เก็บข้อมูลเดิมไว้ใน msg
    msg.productionDate = d;
    msg.pendingLotCount = count;
    msg.dateSource = source;

    node.status({
        fill: source === "PENDING" ? "yellow" : "green",
        shape: "dot",
        text: d + (
            source === "PENDING"
                ? " | " + count + " pending lot(s)"
                : " | latest production"
        )
    });

    return msg;
}

node.error("No production date found");
return null;

var productionDate = global.get("sendAllRejectDate");

if (!productionDate) {
    node.error("Please select Production Date before SEND ALL PROD");
    return null;
}

// ป้องกันค่าผิดรูปแบบก่อนนำไปใช้ใน SQL
if (!/^\d{4}-\d{2}-\d{2}$/.test(String(productionDate))) {
    node.error("Invalid Production Date: " + productionDate);
    return null;
}

msg.productionDate = productionDate;

msg.topic = `
WITH SuccessfulProd AS
(
    SELECT DISTINCT TRIM(lotNo) AS lotNo
    FROM PIS_API_RESULT
    WHERE IsSuccess = 1
      AND OutputDetailId IS NULL
)
SELECT DISTINCT
    CAST(P.[Prod Date] AS date) AS ProductionDate,
    TRIM(P.[Lot No.]) AS LotNo
FROM PIS_PRD_ORDER P
INNER JOIN SuccessfulProd S
    ON TRIM(P.[Lot No.]) = S.lotNo
WHERE CAST(P.[Prod Date] AS date) = '${productionDate}'
ORDER BY LotNo;
`;

return msg;

var rows = msg.payload;

if (!Array.isArray(rows)) {
    node.error("Get PROD SKIP Lots did not return an array");
    return null;
}

if (rows.length === 0) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "NO SKIP"
    });

    return null;
}

function sqlEscape(v) {
    return String(v == null ? "" : v).replace(/'/g, "''");
}

var values = rows.map(function (row) {

    var productionDate =
        sqlEscape(String(row.ProductionDate).substring(0, 10));

    var lotNo =
        sqlEscape(String(row.LotNo || "").trim());

    return `(
        '${productionDate}',
        '${lotNo}',
        'SKIP',
        'ALREADY_SENT',
        'Previous PROD API success'
    )`;
}).join(",\n");

msg.topic = `
INSERT INTO dbo.PIS_PROD_SEND_LOG
(
    ProductionDate,
    LotNo,
    Result,
    Reason,
    Detail
)
VALUES
${values};
`;

msg.skipCount = rows.length;

node.status({
    fill: "yellow",
    shape: "dot",
    text: rows.length + " SKIP lot(s)"
});

return msg;
